new_render = r'''async function renderTimeTimeline(){try{if(typeof openArchShell==='function')openArchShell('Time')}catch{}try{if(typeof archDetailStack!=='undefined')archDetailStack=[]}catch{}enterTimeFullscreen();const root=document.getElementById('archDetailContent');if(!root)return;root.classList.add('evia-time-timeline-v1');root.innerHTML='<div class="evia-time-screen"><div class="evia-time-topbar"><div class="evia-time-key"><strong>Key</strong><span class="evia-time-key-item"><i class="evia-time-key-line course"></i>Course</span><span class="evia-time-key-item"><i class="evia-time-key-line time"></i>Time</span><span class="evia-time-key-item"><i class="evia-time-key-line learning"></i>Learning</span></div><button class="evia-time-close" type="button" data-evia-time-close aria-label="Close Time">×</button></div><div class="evia-time-scroll"><div class="evia-time-empty">Loading timeline…</div></div></div>';const [entries,learning]=await Promise.all([getEvidenceEntries(),Promise.resolve(getLearningEntries())]),dates=profileDates(),start=dateFor(dates.start),end=dateFor(dates.end),scroll=root.querySelector('.evia-time-scroll');if(!start||!end||end<=start){scroll.innerHTML='<div class="evia-time-stage" style="height:520px"><div class="evia-time-empty">Add the course start and end dates in Learner Profile to show the Time timeline.</div></div>';return}const events=buildTimelineEvents(entries,learning),months=monthKeysBetween(start,end),time=timeProgressPercent(),course=currentCourseProgress(),learn=learningProgressPercent(),stageHeight=Math.max(1100,months.length*138+events.length*44),pad=40,height=stageHeight-(pad*2),y=p=>pad+(height*((clampPercent(p)||0)/100)),currentMonth=monthKey(new Date()),archive=readJson(MONTH_ARCHIVE_KEY,{}),monthSides=new Map(months.map((key,index)=>[key,index%2===0?'right':'left']));let lastY=pad-52;const eventRows=[];for(const event of events){const eventMonth=monthKey(event.date),pos=trackPosition(event.date,start,end),monthPos=trackPosition(monthStart(eventMonth),start,end),base=y(pos),floor=y(monthPos)+50,row=Math.max(base,floor,lastY+54),side=monthSides.get(eventMonth)||'right';lastY=Math.min(stageHeight-pad-10,row);eventRows.push(compactEventMarkup(event,lastY,side))}const monthRows=months.map((key,index)=>{const marker=y(trackPosition(monthStart(key),start,end)),txt=monthMarkerText(key),future=key>currentMonth,data=monthData(key,entries,learning,events),has=data.evidence.length||data.learning.length,downloaded=Boolean(archive?.[key]?.updatedAt),name=monthName(key),side=index%2===0?'right':'left';return`<div class="evia-time-month-marker side-${side}${future?' future':''}" style="bottom:${Math.round(marker)}px" data-month="${esc(key)}"><div class="evia-time-month-circle"><strong>${esc(txt.month)}</strong><small>${esc(txt.year)}</small></div>${has&&!future?`<button class="evia-time-pack-button${downloaded?' downloaded':''}" type="button" data-evia-month-pack="${esc(key)}">${downloaded?`&#10003; ${esc(name)} pack downloaded`:`Download ${esc(name)} pack`}</button><span class="evia-time-pack-status" aria-live="polite"></span>`:''}</div>`}).join('');const today=time===null?'':`<span class="evia-time-today" data-evia-today="true" style="bottom:${Math.round(y(time))}px" aria-label="Today"><span class="evia-time-today-label">TODAY</span></span>`;scroll.innerHTML=`<div class="evia-time-stage" style="height:${Math.round(stageHeight)}px"><div class="evia-time-tracks" aria-hidden="true"><span class="evia-time-track base course"></span><span class="evia-time-track base time"></span><span class="evia-time-track base learning"></span><span class="evia-time-track fill course" style="height:${course??0}%"></span><span class="evia-time-track fill time" style="height:${time??0}%"></span><span class="evia-time-track fill learning" style="height:${learn??0}%"></span></div><span class="evia-time-boundary start" style="bottom:${pad}px">Course start</span><span class="evia-time-boundary end" style="bottom:${stageHeight-pad}px">Course end</span>${monthRows}${today}${eventRows.join('')}${events.length?'':'<div class="evia-time-empty">No evidence or learning has been recorded on the timeline yet.</div>'}</div>`;const screen=root.querySelector('.evia-time-screen');if(screen){screen.dataset.courseProgress=course===null?'':String(course);screen.dataset.timeProgress=time===null?'':String(time);screen.dataset.learningProgress=learn===null?'':String(learn)}requestAnimationFrame(()=>{const marker=scroll.querySelector('[data-evia-today="true"]');if(marker)scroll.scrollTop=Math.max(0,marker.offsetTop-(scroll.clientHeight*.56));else scroll.scrollTop=scroll.scrollHeight})}
'''
time = replace_section(
    time,
    r'async function renderTimeTimeline\(\)\{.*?\}\n(?=function pdfSafe\()',
    new_render,
    'timeline renderer',
)

TIME.write_text(time, encoding='utf-8')

index = INDEX.read_text(encoding='utf-8')
old_url = '<script src="./evia-approved-time-monthly-packs-v1.js?v=3"></script>'
new_url = '<script src="./evia-approved-time-monthly-packs-v1.js?v=4"></script>'
if index.count(old_url) != 1:
    raise SystemExit(f'index script version: expected 1 match, found {index.count(old_url)}')
INDEX.write_text(index.replace(old_url, new_url, 1), encoding='utf-8')

manifest = MANIFEST.read_text(encoding='utf-8')
old_manifest = "'./evia-approved-time-monthly-packs-v1.js?v=3'"
new_manifest = "'./evia-approved-time-monthly-packs-v1.js?v=4'"
if manifest.count(old_manifest) != 1:
    raise SystemExit(f'manifest script version: expected 1 match, found {manifest.count(old_manifest)}')
MANIFEST.write_text(manifest.replace(old_manifest, new_manifest, 1), encoding='utf-8')

test = TEST.read_text(encoding='utf-8')
test = test.replace('evia-approved-time-monthly-packs-v1.js?v=3', 'evia-approved-time-monthly-packs-v1.js?v=4')
test = test.replace("await expect(report).toContainText('5th - EPA Practice - Interview');", "await expect(report.locator('.evia-timeline-event-date')).toHaveText('5th');\n  await expect(report).toContainText('EPA Practice - Interview');")
test = test.replace("await expect(evidence).toContainText('4th - Safe working');", "await expect(evidence.locator('.evia-timeline-event-date')).toHaveText('4th');\n  await expect(evidence).toContainText('Safe working');")
test = test.replace("expect(manifest).toContain(\"'./evia-approved-time-monthly-packs-v1.js?v=3'\")", "expect(manifest).toContain(\"'./evia-approved-time-monthly-packs-v1.js?v=4'\")")
marker = "  await expect(page.locator('.evia-time-today-label')).toHaveText('TODAY');\n"
addition = "  await expect(page.locator('.evia-time-today-label')).toHaveText('TODAY');\n  await expect(page.locator('.evia-time-month-marker.side-left')).toHaveCount(6);\n  await expect(page.locator('.evia-time-month-marker.side-right')).toHaveCount(6);\n  await expect(page.locator('.evia-timeline-event.side-left, .evia-timeline-event.side-right').first()).toBeVisible();\n"
if test.count(marker) != 1:
    raise SystemExit('test milestone assertion insertion point not found')
test = test.replace(marker, addition, 1)
TEST.write_text(test, encoding='utf-8')
